cd /Users/luwei/work/Controversy/data/hive
echo "##### hive-project.yaml.example (head 90) #####"; head -90 config/hive-project.yaml.example
echo; echo "##### .github contents #####"; find .github -type f -exec echo "--- {} ---" \; -exec head -20 {} \;

cd /Users/luwei/work/Controversy/data/console
echo "=== lock.yml 总行数 ==="; wc -l .github/workflows/auto-triage.lock.yml
echo; echo "=== 顶层 jobs: 与 job 名 + 各 job 的 permissions/needs/if ==="
awk '
/^jobs:/{injobs=1}
injobs && /^  [a-zA-Z._-]+:/{print "JOB " $0}
injobs && /^    (permissions|needs|runs-on|if|timeout-minutes):/{print "    "$0}
injobs && /^      [a-z-]+: (read|write|none)/{print "      "$0}
' .github/workflows/auto-triage.lock.yml
echo; echo "=== 关键步骤名(- name:) ==="
grep -nE '^\s+- name: ' .github/workflows/auto-triage.lock.yml | head -60

